/**
 * Resolve a presentation-safe Turn snapshot.
 *
 * Prefer the Turn feature's snapshot surface so callers never
 * depend directly on mutable domain state.
 */
function getFrameHelmTurnUiSnapshot() {
  const turnApi =
    getFrameHelmTurnUiTurnApi();


  if (
    turnApi.state !==
    undefined
  ) {
    return (
      turnApi.state ??
      null
    );
  }


  return (
    turnApi.current
      ?.snapshot?.() ??
    null
  );
}

